function x({registerIndicator:B,nulls:y}){B({id:"oa-brar",name:"Bull-Bear Power Ratio (BRAR)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:26,min:1,max:5e3,step:1,tooltip:"Rolling window for summation (traditional: 26)"}],plots:[{key:"br",type:"line",title:"BR",style:{color:"#00bcd4",lineWidth:2}},{key:"ar",type:"line",title:"AR",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:100,title:"Equilibrium",color:"#787b86",lineStyle:"dotted"}],calc(i,A){const l=Math.max(1,Math.min(5e3,Math.floor(Number(A.period)||26))),t=i.length,d=new Array(t).fill(NaN),h=new Array(t).fill(NaN),a=new Array(t).fill(0),u=new Array(t).fill(0),c=new Array(t).fill(0),m=new Array(t).fill(0);let s=0,r=0,f=0,n=0;for(let e=0;e<t;e++){const p=i[e].high,b=i[e].low,o=i[e].open,N=Number.isFinite(p)&&Number.isFinite(b)&&Number.isFinite(o);if(N){const w=e>0&&Number.isFinite(i[e-1].close)?i[e-1].close:o;a[e]=Math.max(0,p-w),u[e]=Math.max(0,w-b),c[e]=Math.max(0,p-o),m[e]=Math.max(0,o-b)}s+=a[e],r+=u[e],f+=c[e],n+=m[e],e>=l&&(s-=a[e-l],r-=u[e-l],f-=c[e-l],n-=m[e-l]),N&&(d[e]=r!==0?s/r*100:100,h[e]=n!==0?f/n*100:100)}return{br:y(d),ar:y(h)}}})}export{x as default};
